"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-dialog";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { ScrollArea, type ScrollAreaProps } from "@/components/ui/scroll-area";
export type DialogProps = React.ComponentProps<typeof Primitive.Root>;
export function Dialog(props: DialogProps) {
  return <Primitive.Root {...props} />;
}
export type DialogTriggerProps = React.ComponentProps<typeof Primitive.Trigger>;
export function DialogTrigger(props: DialogTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="dialog-trigger"
      data-part="trigger"
      data-dialog-open=""
      {...props}
    />
  );
}
export type DialogPortalProps = React.ComponentProps<typeof Primitive.Portal>;
export function DialogPortal(props: DialogPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type DialogOverlayProps = React.ComponentProps<typeof Primitive.Overlay>;
export function DialogOverlay({
  className,
  ref,
  ...props
}: DialogOverlayProps) {
  const flowRef = useFlowAppearance<HTMLDivElement>(true, ref, "fade");
  return (
    <Primitive.Overlay
      ref={flowRef}
      data-slot="dialog-overlay"
      data-part="overlay"
      className={cn(
        "v-scrim fixed inset-0 bg-[var(--v-scrim)] z-[calc(var(--z-dialog)-1)]",
        className,
      )}
      {...props}
    />
  );
}
export const dialogContentVariants = cva(
  "v-dialog [position:fixed] [inset:0] [margin:auto] [width:min(520px,calc(100%_-_48px))] [height:fit-content] [background:var(--v-canvas)] [border-radius:var(--r-sheet)] [padding:var(--s-8)] [z-index:var(--z-dialog)] [display:grid] [box-shadow:var(--shadow-float),inset_0_0_0_1px_var(--v-border)] [gap:var(--s-4)]",
);
export type DialogContentProps = React.ComponentProps<
  typeof Primitive.Content
> & {
  showCloseButton?: boolean;
  appearance?: "confirmation" | "editor" | "exhibit";
};
export function DialogContent({
  className,
  ref,
  children,
  showCloseButton = false,
  appearance,
  ...props
}: DialogContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const flowRef = useFlowAppearance<HTMLDivElement>(true, morphRef, "enter");
  return (
    <Primitive.Portal>
      <DialogOverlay />
      <Primitive.Content
        ref={flowRef}
        data-slot="dialog-content"
        data-part="content"
        data-appearance={appearance}
        data-morph={appearance ? "both" : undefined}
        data-r={appearance ? "css" : undefined}
        data-stable-hit=""
        className={cn(dialogContentVariants(), className)}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogClose asChild>
            <Button
              variant="ghost"
              aria-label="Close"
              className="v-dialog__close"
            >
              <Icon name="x" />
            </Button>
          </DialogClose>
        )}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
/** Bounded body; header and actions remain reachable while native content scrolls. */
export function DialogBody({
  className,
  viewportProps,
  ...props
}: ScrollAreaProps) {
  return (
    <ScrollArea
      variant="plain"
      type="always"
      className={cn("v-dialog__body", className)}
      viewportProps={{ tabIndex: -1, ...viewportProps }}
      {...props}
    />
  );
}
export type DialogHeaderProps = React.ComponentProps<"div">;
export function DialogHeader({ className, ...props }: DialogHeaderProps) {
  return (
    <div
      data-slot="dialog-header"
      data-part="header"
      className={cn(
        "v-dialog__head flex items-start justify-between gap-[var(--s-4)]",
        className,
      )}
      {...props}
    />
  );
}
export type DialogFooterProps = React.ComponentProps<"div">;
export function DialogFooter({ className, ...props }: DialogFooterProps) {
  return (
    <div
      data-slot="dialog-footer"
      data-part="footer"
      className={cn(
        "v-dialog__actions flex gap-[var(--s-3)] justify-end mt-[var(--s-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type DialogTitleProps = React.ComponentProps<typeof Primitive.Title>;
export function DialogTitle({ className, ...props }: DialogTitleProps) {
  return (
    <Primitive.Title
      data-slot="dialog-title"
      data-part="title"
      className={cn(
        "v-section font-[family-name:var(--font-display)] text-[24px] leading-[1.15] tracking-[-0.01em] pt-1.5 font-medium",
        className,
      )}
      {...props}
    />
  );
}
export type DialogDescriptionProps = React.ComponentProps<
  typeof Primitive.Description
>;
export function DialogDescription({
  className,
  ...props
}: DialogDescriptionProps) {
  return (
    <Primitive.Description
      data-slot="dialog-description"
      data-part="description"
      className={cn(
        "v-body-2 text-[15px] leading-[1.5] text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type DialogCloseProps = React.ComponentProps<typeof Primitive.Close>;
export function DialogClose(props: DialogCloseProps) {
  return (
    <Primitive.Close
      data-slot="dialog-close"
      data-part="close"
      data-close=""
      {...props}
    />
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-scrim:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  position: fixed;
  inset: 0;
  background: var(--v-scrim);
  z-index: var(--z-sheet);
}
.v-dialog__head:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-4);
}
.v-dialog__actions:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  display: flex;
  gap: var(--s-2);
  justify-content: flex-end;
}
/* Scrim paint and retained close use the shared opacity-only Motion lane. */
.v-dialog:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  animation: none;
}
.v-dialog__head:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  align-items: start;
}
.v-dialog__head:where([data-slot="dialog"], [data-slot^="dialog-"]) .v-section {
  font-size: 24px;
  line-height: 1.15;
  padding-top: 6px;
}
.v-dialog:where([data-slot="dialog"], [data-slot^="dialog-"]) > .v-body-2 {
  max-width: 52ch;
}
.v-dialog__actions:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  margin-top: var(--s-2);
  gap: var(--s-3);
}
.v-dialog:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  scrollbar-gutter: stable;
}
.v-dialog:where([data-slot="dialog"], [data-slot^="dialog-"]) {
  scrollbar-gutter: stable;
}
@keyframes v-scrim-in {
  from {
    opacity: 0;
  }
}
@keyframes v-dialog-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.985);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="dialog"],
  [data-slot^="dialog-"],
  [data-slot="dialog"]::before,
  [data-slot="dialog"]::after,
  [data-slot^="dialog-"]::before,
  [data-slot^="dialog-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

/* A long dialog stays inside the screen; its actions remain reachable. */
[data-slot="dialog-content"] {
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  overscroll-behavior: contain;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr);
}
[data-slot="dialog-title"],
[data-slot="dialog-description"] {
  overflow-wrap: anywhere;
}
[data-slot="dialog-footer"] {
  flex-wrap: wrap;
}
@media (max-width: 640px) {
  [data-slot="dialog-content"] {
    width: calc(100% - 24px);
    padding: var(--s-6);
  }
}

.v-dialog .v-dialog__close {
  position: absolute;
  top: 12px;
  right: 12px;
  min-width: 44px;
  min-height: 44px;
  padding: 0;
}
.v-dialog[data-appearance] {
  width: min(580px, calc(100% - 40px));
  padding: 28px;
  gap: 20px;
  overflow: visible;
  background: var(--v-paper);
  border-radius: 28px;
  --mfill: var(--v-paper);
  --mstroke: var(--v-border);
  box-shadow: var(--shadow-float);
}
.v-dialog[data-appearance]:has(> svg [data-morph-body]) {
  background: transparent;
}
.v-dialog[data-appearance] .v-dialog__head {
  display: grid;
  padding-right: 48px;
  gap: 10px;
}
.v-dialog[data-appearance] [data-slot="dialog-title"] {
  margin: 0;
  max-width: 22ch;
}
.v-dialog[data-appearance] [data-slot="dialog-description"] {
  margin: 0;
  max-width: 48ch;
}
.v-dialog[data-appearance] .v-dialog__body {
  --h: min(480px, calc(100dvh - 330px));
  height: auto;
  min-height: 0;
  max-height: var(--h);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.v-dialog[data-appearance]
  .v-dialog__body[data-slot].-plain
  > [data-slot="scroll-area-viewport"] {
  height: auto;
  max-height: var(--h);
  padding: 4px 20px 12px 4px;
}
.v-dialog[data-appearance] .v-dialog__actions {
  border-top: 1px solid var(--v-border);
  padding-top: 18px;
  margin: 0;
}
.v-dialog[data-appearance="confirmation"] {
  width: min(480px, calc(100% - 40px));
  --mfill: var(--v-yellow-soft);
  background: var(--v-yellow-soft);
  border-radius: 24px;
}
.v-dialog[data-appearance="exhibit"] {
  width: min(800px, calc(100% - 40px));
}
.v-dialog__stamp {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--v-blue);
  color: var(--ink-fixed);
}
.v-dialog__exhibit {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 28px;
  align-items: center;
}
.v-dialog__exhibit img {
  display: block;
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: 18px;
}
.v-dialog__exhibit dl {
  display: grid;
  gap: 8px;
  margin: 16px 0;
  font-size: 13px;
}
.v-dialog__exhibit dd {
  margin: 0 0 12px;
  color: var(--v-text-2);
}
.v-dialog-example {
  display: grid;
  gap: 20px;
  justify-items: start;
  padding: 18px;
  min-width: 0;
}
.v-dialog-example__slip {
  display: grid;
  gap: 12px;
  width: 100%;
  padding: 24px;
  border-left: 3px solid var(--v-brand);
  background: var(--v-paper);
  border-radius: 0 20px 20px 0;
}
.v-dialog-example p {
  margin: 0;
  line-height: 1.6;
}
.v-dialog-example__eyebrow {
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--v-text-2);
}
@media (max-width: 540px) {
  .v-dialog[data-appearance] {
    padding: 22px;
    gap: 16px;
    max-height: calc(100dvh - 40px);
  }
  .v-dialog[data-appearance] .v-dialog__body {
    max-height: calc(100dvh - 310px);
  }
  .v-dialog__exhibit {
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }
  .v-dialog__exhibit img {
    aspect-ratio: 1.7;
  }
  .v-dialog[data-appearance] [data-slot="dialog-title"] {
    font-size: 23px;
  }
}

}
